var ROGO=ROGO||{};ROGO.lang=ROGO.lang||{},ROGO.lang.components={},ROGO.lang.get_string=function(name,component,args){if(component=component||"default",!ROGO.lang.components[component]||!ROGO.lang.components[component][name])return ROGO.log("Missing string: "+component+":"+name,"error"),"[["+component+":"+name+"]]";var string=ROGO.lang.components[component][name],match_count=0;return string.replace(/%s/g,function(match){return Array.isArray(args)&&args[match_count]?args[match_count++]:(ROGO.log("Missing parametr for string: "+component+":"+name,"warn"),match)})},ROGO.lang.set_string=function(string,name,component){component=component||"default",ROGO.lang.components[component]||(ROGO.lang.components[component]={}),ROGO.lang.components[component][name]=string},ROGO.lang.set_strings=function(strings,component){component=component||"default";for(var name in strings)ROGO.lang.set_string(strings[name],name,component)},ROGO.log=function(message,level){if(console)switch(level){case"error":console.error?console.error(message):console.log("Error: "+message);break;case"warn":console.warn?console.warn(message):console.log("Warn: "+message);break;case"info":console.info?console.info(message):console.log("Info: "+message);break;case"trace":console.error&&console.trace?console.error(message,console.trace()):console.log("Error: "+message);break;default:console.log(message)}};